import{_ as s,C as r,o,c as l,j as a,a as t,b as d,w as i,E as c,a3 as p,a2 as h}from"./chunks/framework.CDA9RsCr.js";const y=JSON.parse('{"title":"Use Cases","description":"","frontmatter":{},"headers":[],"relativePath":"en/use-cases/scenarios.md","filePath":"en/use-cases/scenarios.md","lastUpdated":1794581028000}'),u={name:"en/use-cases/scenarios.md"};function m(w,e,g,f,v,b){const n=r("Mermaid");return o(),l("div",null,[e[1]||(e[1]=a("h1",{id:"use-cases",tabindex:"-1"},[t("Use Cases "),a("a",{class:"header-anchor",href:"#use-cases","aria-label":'Permalink to "Use Cases"'},"​")],-1)),e[2]||(e[2]=a("h2",{id:"interactive-draws-during-a-stream",tabindex:"-1"},[t("Interactive draws during a stream "),a("a",{class:"header-anchor",href:"#interactive-draws-during-a-stream","aria-label":'Permalink to "Interactive draws during a stream"'},"​")],-1)),e[3]||(e[3]=a("p",null,"The streamer starts a keyword interaction; viewers who send the keyword are auto-added to the pool, and winners are drawn at random when it stops.",-1)),(o(),d(p,null,{default:i(()=>[c(n,{id:"mermaid-9",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20A%5BLog%20in%5D%20--%3E%20B%5BAdd%20rooms%5D%0A%20%20%20%20B%20--%3E%20C%5BSet%20keyword%20and%20winner%20count%5D%0A%20%20%20%20C%20--%3E%20D%5BStart%5D%0A%20%20%20%20D%20--%3E%20E%5BStop%20and%20draw%5D%0A%20%20%20%20E%20--%3E%20F%5BResult%20written%20to%20history%5D%0A"})]),fallback:i(()=>[...e[0]||(e[0]=[t(" Loading... ",-1)])]),_:1})),e[4]||(e[4]=h('<p>While the draw runs you can watch the stream and the danmaku feed on the same screen instead of switching to a browser to check whether people are actually sending the keyword.</p><h2 id="monitoring-several-rooms-at-once" tabindex="-1">Monitoring several rooms at once <a class="header-anchor" href="#monitoring-several-rooms-at-once" aria-label="Permalink to &quot;Monitoring several rooms at once&quot;">​</a></h2><p>The room list takes any number of rooms. <code>ConnectLiveRooms</code> opens an independent danmaku connection per room, the participant pools merge, and the draw picks from the combined pool. A room that fails to connect is named in the start notification rather than being silently ignored.</p><p>The stream preview and danmaku panel only follow the <em>selected</em> room, so switching the preview never disturbs a running pool.</p><h2 id="switching-configurations-per-scenario" tabindex="-1">Switching configurations per scenario <a class="header-anchor" href="#switching-configurations-per-scenario" aria-label="Permalink to &quot;Switching configurations per scenario&quot;">​</a></h2><p>Save multiple <strong>Profiles</strong> (draw-config sets). Each independently stores its keyword, winner count, rooms, background and history. Switching a profile switches all of it, history included.</p><div class="tip custom-block"><p class="custom-block-title">What a Profile is</p><p>A Profile is a &quot;draw-configuration set&quot;, <strong>not a Bilibili account</strong>.</p><ul><li>One Bilibili login (Cookie / QR) is reused by every Profile</li><li>For example: a daily draw, a fan festival and a New-Year special each get a Profile</li><li>Each Profile keeps its latest 100 draw records</li></ul></div><h2 id="themed-events" tabindex="-1">Themed events <a class="header-anchor" href="#themed-events" aria-label="Permalink to &quot;Themed events&quot;">​</a></h2><p>Light / dark mode plus background presets fit different moods:</p><ul><li><strong>Default gradient</strong> — everyday use, brand-pink accent</li><li><strong>Spring festival / Beach</strong> — bundled images whose dominant color becomes the accent (red-ish and blue-ish respectively)</li></ul><p>You can also upload your own background on any profile; a custom image beats the preset.</p><h2 id="reviewing-past-draws" tabindex="-1">Reviewing past draws <a class="header-anchor" href="#reviewing-past-draws" aria-label="Permalink to &quot;Reviewing past draws&quot;">​</a></h2><p>Every result is recorded with keyword, winner count, time and the full list. Useful for:</p><ul><li>Showing the list when someone questions the outcome in chat</li><li>Exporting a Markdown archive after an event</li><li>Comparing participation between sessions</li></ul><div class="warning custom-block"><p class="custom-block-title">Not supported</p><p>This is a local desktop app. It does <strong>not</strong> provide:</p><ul><li>Cloud sync of configs or history</li><li>Auto-announcing winners to danmaku</li><li>Automatic prize distribution</li></ul><p>Winner lists are shown and exported locally only.</p></div>',15))])}const P=s(u,[["render",m]]);export{y as __pageData,P as default};
